        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
